#include<bits/stdc++.h>
using namespace std; const int N=36;double R[N][N],z[N];long long Q[N][N],nodes=0,CAP=200000000;bool found=false,cap=false;double bound=7.99999999;void go(int k,double q){if(found||cap)return;if(++nodes>CAP){cap=true;return;}if(k<0){long long s=0;for(int i=0;i<N;i++)for(int j=0;j<N;j++)s+=(long long)z[i]*Q[i][j]*(long long)z[j];if(s>0&&s<160){found=true;cout<<"NORM "<<s<<"/20 ";for(auto a:z)cout<<(int)a<<' ';cout<<endl;}return;}double a=0;for(int j=k+1;j<N;j++)a-=R[k][j]*z[j]/R[k][k];double r=sqrt(max(0.,bound-q))/R[k][k];int lo=ceil(a-r-1e-9),hi=floor(a+r+1e-9),mid=round(a);for(int s=0;s<=max(mid-lo,hi-mid);s++)for(int sg:s?vector<int>{-1,1}:vector<int>{1}){int x=mid+sg*s;if(x<lo||x>hi)continue;z[k]=x;double v=R[k][k]*(x-a);if(q+v*v<=bound+1e-8)go(k-1,q+v*v);if(found||cap)return;}}
int main(int argc,char**argv){if(argc>3)CAP=atoll(argv[3]);ifstream f(argv[1]),g(argv[2]);for(auto&a:R)for(auto&v:a)f>>v;for(auto&a:Q)for(auto&v:a)g>>v;go(N-1,0);cout<<"END nodes "<<nodes<<" found "<<found<<" cap "<<cap<<endl;}
